        <button type="button" data-toast="已開啟付款核准清單。" class="task-item group"><span class="task-icon bg-[#edf3ff] text-[#718bd1]"><svg class="size-4" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M4 5.5h12v9H4zM6.5 3.5v4M13.5 3.5v4M7 10h6" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span class="min-w-0 flex-1 text-left"><span class="block text-xs font-semibold text-[#38465c]">付款核准</span><span class="mt-1 block truncate text-[10px] text-[#9aa5b5]">採購部有 5 筆請款待確認</span></span><svg class="size-4 shrink-0 text-[#bbc3cf] transition group-hover:translate-x-0.5 group-hover:text-[#7185a6]" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m7.5 4 6 6-6 6" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
